import java.io.*
import java.util.*

const val MOD = 998244353L

fun power(a: Long, b: Long): Long {
    var res = 1L
    var x = a % MOD
    if (x < 0) x += MOD
    var e = b
    while (e > 0) {
        if (e and 1L == 1L) res = res * x % MOD
        x = x * x % MOD
        e = e shr 1
    }
    return res
}

lateinit var fact: LongArray
lateinit var invFact: LongArray

fun comb(n: Int, k: Int): Long {
    if (k < 0 || n < 0 || k > n) return 0L
    return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val p = st.nextToken().toInt()
    val s = st.nextToken().toInt()
    val r = st.nextToken().toInt()

    val maxN = s + p + 10
    fact = LongArray(maxN)
    invFact = LongArray(maxN)
    fact[0] = 1
    for (i in 1 until maxN) fact[i] = fact[i - 1] * i % MOD
    invFact[maxN - 1] = power(fact[maxN - 1], MOD - 2)
    for (i in maxN - 1 downTo 1) invFact[i - 1] = invFact[i] * i % MOD

    if (s == 0) {
        println(power(p.toLong(), MOD - 2))
        return
    }

    // inverses of 1..p
    val inv = LongArray(p + 2)
    for (i in 1..p + 1) inv[i] = power(i.toLong(), MOD - 2)

    val total = comb(s - r + p - 1, p - 1)

    var ans = 0L
    val start = if (r > 1) r else 1
    for (m in start..s) {
        for (k in 0..p - 1) {
            val rem = s - m.toLong() * (k + 1)
            if (rem < 0) break
            val remI = rem.toInt()
            val j = p - 1 - k
            var ways: Long
            if (j == 0) {
                ways = if (remI == 0) 1L else 0L
            } else {
                ways = 0L
                var i = 0
                while (i <= j) {
                    val t = remI - i.toLong() * m
                    if (t < 0) break
                    val term = comb(j, i) * comb(t.toInt() + j - 1, j - 1) % MOD
                    if (i % 2 == 0) {
                        ways = (ways + term) % MOD
                    } else {
                        ways = (ways - term + MOD) % MOD
                    }
                    i++
                }
            }
            if (ways != 0L) {
                val contrib = comb(p - 1, k) * ways % MOD * inv[k + 1] % MOD
                ans = (ans + contrib) % MOD
            }
        }
    }

    val res = ans * power(total, MOD - 2) % MOD
    println(res)
}
